设计方案如下，该 Schema 使用了标准的 JSON Schema 规范定义，以便大模型能够完美理解参数要求：
{
  "name": "generate_a3_quiz",
  "description": "根据 A3 题库规范，生成或调取一道特定知识点和认知层级的练习题。",
  "inputSchema": {
    "type": "object",
    "properties": {
      "kp_id": {
        "type": "string",
        "description": "知识点图谱 ID，例如 AI_014"
      },
      "bloom_level": {
        "type": "string",
        "description": "布鲁姆认知目标层级",
        "enum": ["Remember", "Understand", "Apply", "Analyze", "Evaluate", "Create"]
      },
      "question_type": {
        "type": "string",
        "description": "题型偏好",
        "enum": ["multiple_choice", "short_answer", "open_ended"]
      }
    },
    "required": ["kp_id", "bloom_level"]
  }
}
